'use strict';
const COLORS={white:{name:'우유빛',hex:'#fffdf2',price:25},blue:{name:'파랑',hex:'#80a5dd',price:30},yellow:{name:'노랑',hex:'#f3d46b',price:25},beige:{name:'베이지',hex:'#dfc9a7',price:25},red:{name:'빨강',hex:'#df817c',price:30},sky:{name:'하늘색',hex:'#b0dce9',price:55},cream:{name:'연노랑',hex:'#f7edb0',price:55},mist:{name:'연하늘색',hex:'#d9edf0',price:110},pink:{name:'연분홍',hex:'#efc1cc',price:55},lavender:{name:'라벤더',hex:'#c7bbdf',price:55},rainbow:{name:'무지개',hex:'linear-gradient(135deg,#eea3a7,#f6dd8c,#b7d7bd,#a9cae7,#c4b0df)',price:700},diamond:{name:'다이아몬드',hex:'#e2f8ff',price:1200},gold:{name:'골드',hex:'#eac061',price:900}};
const BASIC=['white','blue','yellow','beige','red'];const KEY='petite-bloom-v1';
function fresh(){return {coins:50,pots:[null,null,null],seeds:[{id:'wild',kind:'wild',count:6,gen:1}],found:[],speed:0,auto:false,luck:false,total:0};}
let state=fresh();try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.pots)&&s.pots.length===3&&Array.isArray(s.seeds)&&Array.isArray(s.found)&&Number.isFinite(s.coins))state={...state,...s};}catch{}
let selected=state.seeds.find(s=>s.count>0)?.id||'wild',tab='seeds',toastTimer;
const $=id=>document.getElementById(id);function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('save').textContent='● 자동 저장';}catch{$('save').textContent='저장 불가 · 창을 유지해주세요';}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function rnd(a){return a[Math.floor(Math.random()*a.length)];}function seedName(s){return s.kind==='wild'?'두근두근 씨앗':s.kind==='clone'?COLORS[s.color].name+' 씨앗':'교배 씨앗';}
function addSeed(s){let id=s.kind==='clone'?'clone-'+s.color+'-'+s.gen:s.kind==='wild'?'wild':'cross-'+s.parents.join('-')+'-'+s.gen;let found=state.seeds.find(x=>x.id===id);if(found)found.count++;else state.seeds.push({...s,id,count:1});return id;}
function stage(p,now=Date.now()){if(!p)return'empty';if(p.color)return'flower';if(!p.watered)return'water';if(!p.pruned)return now-p.watered>=5000?'prune':'sprout';return now>=p.ready?'bud':'grow';}
function mix(a,b,r=Math.random()){const recipe={ 'blue|white':'sky','white|yellow':'cream','cream|sky':'mist','red|white':'pink','blue|red':'lavender'};let c=recipe[[a,b].sort().join('|')];return c?(r<.3?a:r<.6?b:c):(r<.5?a:b);}
function roll(seed){if(seed.kind==='clone')return seed.color;let r=Math.random(),boost=state.luck?2:1;if(r<.001*boost)return'diamond';if(r<.003*boost)return'gold';if(r<.006*boost)return'rainbow';return seed.kind==='cross'?mix(seed.parents[0],seed.parents[1]):rnd(BASIC);}
function flowerSvg(color,st='flower',id='a'){const c=COLORS[color]?.hex||'#a4ba7b';const fill=color==='rainbow'?`url(#rain${id})`:c;let full=st==='flower',growing=['grow','bud','flower'].includes(st),sprout=['sprout','prune'].includes(st);return `<svg viewBox="0 0 160 200" aria-hidden="true"><defs><linearGradient id="rain${id}" x2="1" y2="1"><stop stop-color="#efa2b5"/><stop offset=".3" stop-color="#f4d881"/><stop offset=".55" stop-color="#b6d9ad"/><stop offset=".8" stop-color="#a9cde9"/><stop offset="1" stop-color="#c9b2df"/></linearGradient></defs><ellipse cx="80" cy="186" rx="52" ry="7" fill="#687d4b22"/>${growing?`<g class="bloom"><path d="M80 148 Q90 115 79 66" fill="none" stroke="#749668" stroke-width="6" stroke-linecap="round"/><path d="M82 127 Q42 130 43 102 Q71 100 82 127M83 113 Q115 110 117 88 Q89 86 83 113" fill="#8ca975"/><path d="M80 143 Q103 146 111 126 Q89 121 80 143" fill="#a2b98b"/>${full?Array.from({length:8},(_,i)=>`<ellipse cx="80" cy="43" rx="14" ry="25" transform="rotate(${i*45} 80 66)" fill="${fill}" stroke="#52684b22" stroke-width="1.2"/>`).join('')+`<circle cx="80" cy="66" r="13" fill="#e5b955"/><circle cx="76" cy="62" r="3" fill="#f7dd8c"/>`:`<path d="M80 87 C48 69 63 42 80 48 C97 42 111 69 80 87" fill="#a5bb80" stroke="#7f9f66" stroke-width="2"/><path d="M80 84 Q66 63 80 49" fill="none" stroke="#c5d59c" stroke-width="3"/>`}${['rainbow','diamond','gold'].includes(color)?'<g class="sparkle" fill="#c6ab5e"><path d="m40 44 3 8 8 3-8 3-3 8-3-8-8-3 8-3zm81 21 2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/></g>':''}</g>`:sprout?'<path d="M80 150v-27" stroke="#7e9a6b" stroke-width="5"/><path d="M80 138Q49 137 55 116Q79 114 80 138M80 131Q107 131 106 112Q82 112 80 131" fill="#9bb77e"/>':''}<path d="M43 147h74l-8 37q-29 11-58 0z" fill="#d6a58b"/><path d="M43 147h15l7 43-14-6z" fill="#c69079" opacity=".5"/><rect x="38" y="140" width="84" height="15" rx="5" fill="#e4b99d"/><ellipse cx="80" cy="141" rx="35" ry="5" fill="#8b725b"/><path d="M66 171q3 5 6 0m17 0q3 5 6 0" fill="none" stroke="#936e58" stroke-width="2" stroke-linecap="round"/><path d="M77 178q3 3 6 0" fill="none" stroke="#936e58" stroke-width="1.5"/></svg>`;}
function renderPots(){let focus=document.activeElement?.dataset.pot; $('pots').innerHTML=state.pots.map((p,i)=>{let st=stage(p),text={empty:'씨앗 심기',water:'물 주기',sprout:'싹이 자라고 있어요',prune:'가지치기',grow:'꽃봉우리 기다리는 중',bud:'꽃봉우리 열기',flower:'꽃 살펴보기'}[st];let remaining=p?.ready?Math.max(0,Math.ceil((p.ready-Date.now())/1000)):0;let disabled=['sprout','grow'].includes(st);return `<div class="pot-slot"><div class="plant-view"><button class="plant-button" data-pot="${i}" aria-label="${i+1}번 화분 ${text}" ${disabled?'disabled':''}>${flowerSvg(p?.color,st,i)}${st==='empty'?'<span class="empty-mark">+</span>':''}</button></div><div class="pot-label"><b>${p?.color?COLORS[p.color].name+' 꽃':st==='empty'?'작은 빈 화분':st==='bud'?'두근두근, 개화 준비!':'자라는 중'}</b><small>${p?'· '+p.seed.gen+'세대':'· 0'+(i+1)}</small></div><button class="action ${['water','prune','bud'].includes(st)?'primary':''}" data-pot="${i}" ${disabled?'disabled':''}>${st==='sprout'?Math.max(0,Math.ceil((p.watered+5000-Date.now())/1000))+'초 후 가지치기':st==='grow'?remaining+'초 뒤 꽃봉우리':text}</button>${st==='grow'?`<div class="progress"><i style="width:${Math.min(100,100*(1-remaining/(p.duration/1000)))}%"></i></div>`:''}</div>`;}).join('');if(focus!==undefined)$('pots').querySelector(`button.action[data-pot="${focus}"]`)?.focus({preventScroll:true});}
function render(){ $('coins').textContent=state.coins.toLocaleString();$('seedCount').textContent=state.seeds.reduce((n,s)=>n+s.count,0);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderPots();renderPanel();save();}
function renderPanel(){const head=(title,desc)=>`<div class="panel-heading"><div><h2>${title}</h2><p>${desc}</p></div></div>`;if(tab==='seeds'){$('panel').innerHTML=head('다음 꽃을 골라볼까요?','씨앗을 고른 뒤, 위의 빈 화분을 눌러주세요.')+`<div class="seed-grid">${state.seeds.filter(s=>s.count>0).map(s=>`<button class="seed-card ${s.id===selected?'selected':''}" data-seed="${s.id}"><span class="packet">${s.kind==='wild'?'✿':s.kind==='cross'?'⚘':'❀'}</span><span><strong>${seedName(s)} · ${s.count}</strong><small>${s.kind==='cross'?s.parents.map(c=>COLORS[c].name).join(' × '):s.kind==='clone'?'같은 색으로 피어나요':'5가지 기본색 · 희귀 변이'} · ${s.gen}세대</small></span></button>`).join('')}</div><p class="fine">씨앗이 없어도 괜찮아요. 작은 상점에서 기본 씨앗을 무료로 받을 수 있어요.</p>`;}
if(tab==='breed'){let flowers=state.pots.map((p,i)=>p?.color?{...p,i}:null).filter(Boolean);let options=flowers.map(p=>`<option value="${p.i}">${p.i+1}번 · ${COLORS[p.color].name}</option>`).join('');$('panel').innerHTML=head('둘이 만나, 새로운 색으로','다 자란 서로 다른 화분 2개를 골라요. 부모 꽃은 그대로 남아요.')+(flowers.length<2?'<p class="fine">꽃 두 송이를 피워주세요. 같은 색의 꽃끼리도 교배할 수 있어요.</p>':`<div class="breed-layout"><select id="parentA" aria-label="첫 번째 부모 꽃">${options}</select><span>×</span><select id="parentB" aria-label="두 번째 부모 꽃">${options}</select><button class="primary" id="cross">교배 씨앗 만들기 · 10 G</button></div>`)+`<p class="fine">흰색(우유빛) + 파랑 → 하늘색　·　노랑 + 흰색 → 연노랑　·　하늘색 + 연노랑 → 연하늘색<br>새 색 40% · 각 부모색 30%. 그 외 조합은 각 부모색 50%. 희귀 변이는 별도 확률로 등장해요.</p>`;if($('parentB'))$('parentB').selectedIndex=1;}
if(tab==='collection')$('panel').innerHTML=head(`꽃의 기록 · ${state.found.length} / ${Object.keys(COLORS).length}`,'처음 만난 색은 이곳에 영원히 남아요.')+`<div class="collection-grid">${Object.entries(COLORS).map(([k,c])=>`<div class="flower-tile ${state.found.includes(k)?'':'locked'}"><span class="swatch" style="background:${c.hex}"></span>${state.found.includes(k)?c.name:'???'}</div>`).join('')}</div><p class="fine">기본 희귀 확률: 무지개 0.3% · 골드 0.2% · 다이아몬드 0.1%. 보존 씨앗은 원래 색을 유지해요.</p>`;
if(tab==='shop')$('panel').innerHTML=head('온실에 작은 선물을','꽃을 판매한 골드로 조금 더 편안한 정원을 만들어요.')+`<div class="shop-grid"><div class="shop-card"><h3>♧ 씨앗 나눔</h3><p>기본 씨앗 3개. 보유 기본 씨앗이 3개 미만일 때 받을 수 있어요.</p><button data-buy="seeds" ${(state.seeds.find(s=>s.kind==='wild')?.count||0)>=3?'disabled':''}>무료로 받기</button></div><div class="shop-card"><h3>☀ 햇살 가꾸기 · ${state.speed}/3</h3><p>성장 시간 5초 단축. 최대 30초까지 빨라져요.</p><button data-buy="speed" ${state.speed>=3?'disabled':''}>${state.speed>=3?'모두 배웠어요':(80+state.speed*60)+' G · 배우기'}</button></div><div class="shop-card"><h3>♧ 자동 물뿌리개</h3><p>씨앗을 심으면 자동으로 물을 줘요.</p><button data-buy="auto" ${state.auto?'disabled':''}>${state.auto?'사용 중':'120 G · 구입'}</button></div><div class="shop-card"><h3>✧ 행운의 부적</h3><p>희귀 변이 확률이 2배가 돼요.</p><button data-buy="luck" ${state.luck?'disabled':''}>${state.luck?'사용 중':'250 G · 구입'}</button></div></div>`;}
function openModal(html){$('modalContent').innerHTML=html;if(!$('modal').open)$('modal').showModal();}function showFlower(i,newborn=false){let p=state.pots[i],c=COLORS[p.color];openModal(`<div class="reveal"><p class="eyebrow">${newborn?'새로운 꽃이 피었어요!':'내 온실의 작은 보물'}</p>${flowerSvg(p.color,'flower','modal')}<h2>${c.name} 꽃</h2><p>${p.seed.gen}세대 · ${['rainbow','gold','diamond'].includes(p.color)?'아주 특별한 희귀 꽃':'햇살과 정성으로 피운 꽃'}<br>보존하면 꽃 대신 같은 색의 씨앗 1개를 받아요.</p><div class="modal-actions"><button data-preserve="${i}">씨앗으로 보관</button><button class="primary" data-sell="${i}">${c.price} G에 판매</button></div><p class="fine">교배에 쓰려면 창을 닫고 꽃을 남겨두세요.</p></div>`);}
function potAction(i){let p=state.pots[i],st=stage(p);if(st==='empty'){let seed=state.seeds.find(s=>s.id===selected&&s.count>0);if(!seed){tab='seeds';render();toast('보관함에서 심을 씨앗을 골라주세요.');return;}seed.count--;state.pots[i]={seed:{...seed,count:undefined},watered:state.auto?Date.now():null,pruned:false,duration:45000-state.speed*5000};toast(state.auto?'씨앗을 심고 자동으로 물을 줬어요.':'씨앗을 심었어요. 물을 주세요!');}else if(st==='water'){p.watered=Date.now();toast('촉촉해졌어요! 5초 뒤 가지를 다듬어주세요.');}else if(st==='prune'){p.pruned=true;p.ready=Math.max(Date.now()+1000,p.watered+p.duration);toast('가지를 다듬었어요. 곧 꽃봉우리가 생겨요.');}else if(st==='bud'){p.color=roll(p.seed);state.total++;if(!state.found.includes(p.color))state.found.push(p.color);showFlower(i,true);}else if(st==='flower'){showFlower(i);}render();}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.pot!==undefined)potAction(Number(b.dataset.pot));if(b.dataset.tab){tab=b.dataset.tab;render();document.getElementById('drawer').classList.add('open');}if(b.dataset.seed){selected=b.dataset.seed;render();$('tip').textContent=seedName(state.seeds.find(s=>s.id===selected))+' 선택됨 · 빈 화분을 눌러 심어주세요.';}if(b.dataset.sell!==undefined||b.dataset.preserve!==undefined){let i=Number(b.dataset.sell??b.dataset.preserve),p=state.pots[i];if(!p?.color)return;if(b.dataset.sell!==undefined){state.coins+=COLORS[p.color].price;toast(COLORS[p.color].price+' 골드를 받았어요.');}else{selected=addSeed({kind:'clone',color:p.color,gen:p.seed.gen});toast('같은 색의 보존 씨앗을 보관했어요.');}state.pots[i]=null;$('modal').close();render();}if(b.id==='cross'){let a=+$('parentA').value,z=+$('parentB').value;if(a===z){toast('서로 다른 화분을 골라주세요.');return;}if(state.coins<10){toast('10 골드가 필요해요. 꽃을 판매해보세요.');return;}let pa=state.pots[a],pb=state.pots[z];if(!pa?.color||!pb?.color)return;state.coins-=10;selected=addSeed({kind:'cross',parents:[pa.color,pb.color],gen:Math.max(pa.seed.gen,pb.seed.gen)+1});tab='seeds';toast('교배 씨앗을 만들었어요! 빈 화분에 심어 색을 확인해보세요.');render();}if(b.dataset.buy){let k=b.dataset.buy;if(k==='seeds'){if((state.seeds.find(s=>s.kind==='wild')?.count||0)>=3)return;for(let i=0;i<3;i++)addSeed({kind:'wild',gen:1});toast('기본 씨앗 3개를 받았어요.');}else{if(k==='speed'&&state.speed>=3||k!=='speed'&&state[k])return;let price=k==='speed'?80+state.speed*60:k==='auto'?120:250;if(state.coins<price){toast('골드가 부족해요. 꽃을 판매해보세요.');return;}state.coins-=price;if(k==='speed')state.speed++;else state[k]=true;toast('온실에 새 선물이 도착했어요.');}render();}if(b.classList.contains('close'))$('modal').close();});
$('help').onclick=()=>openModal('<h2>작은 온실에 오신 걸 환영해요</h2><p>① 씨앗을 선택하고 빈 화분에 심어요.<br>② 물을 주고 5초 뒤 가지치기를 해요.<br>③ 물을 준 뒤 약 45초가 지나면 꽃봉우리가 생겨요.<br>④ 꽃봉우리를 눌러 꽃의 색을 발견해요.<br>⑤ 꽃 두 송이를 교배해서 새로운 씨앗을 만들어요.</p><p>꽃을 누르면 판매하거나 같은 색의 씨앗으로 보관할 수 있어요. 희귀 꽃도 기다리고 있답니다.</p><p class="fine">이 브라우저에 자동 저장돼요. 닫아둔 동안에도 물을 주고 가지치기를 끝낸 꽃은 자라요. 브라우저 데이터를 지우면 정원도 초기화돼요.</p>');
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){let r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
let lastSignature='';setInterval(()=>{let sig=state.pots.map(p=>stage(p)+(p?.ready?Math.ceil((p.ready-Date.now())/1000):p?.watered?Math.ceil((p.watered+5000-Date.now())/1000):'')).join();if(sig!==lastSignature){renderPots();lastSignature=sig;}},250);render();


